WITH flagged AS (SELECT *, CASE WHEN LAG(started_at) OVER (PARTITION BY country ORDER BY started_at, id) IS NULL OR started_at > LAG(started_at) OVER (PARTITION BY country ORDER BY started_at, id) + INTERVAL 14 DAYS THEN 1 ELSE 0 END AS is_new_burst FROM sessions), sessionized AS (SELECT *, SUM(is_new_burst) OVER (PARTITION BY country ORDER BY started_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS island_id FROM flagged) SELECT island_id, COUNT(CASE WHEN browser = 'Edge' THEN 1 END) AS edge_count, ROUND(AVG(island_id), 2) AS avg_island_id, SIZE(COLLECT_SET(browser)) AS num_browsers, COUNT_IF(device = 'tablet') AS tablet_events, ROUND(AVG(is_new_burst), 2) AS avg_is_new_burst, COUNT(DISTINCT browser) AS distinct_browsers, GROUPING_ID() AS gid FROM sessionized GROUP BY CUBE (island_id)
